"""Compile exact passenger-model descriptions from supplied vehicle-type tables."""

import argparse
import hashlib
import json
import os
import re
import sys
import tempfile
from collections.abc import Iterator
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from app.ista_data import DataFormatError, _kis_row, normalize_series
from scripts.recover_ista_texts import query, sha256_file

SCHEMA = (
    "CREATE CACHED TABLE KIS.FAHRZEUGTYP(ID INTEGER GENERATED BY DEFAULT AS "
    "IDENTITY(START WITH 1) NOT NULL,NAME CHARACTER(4) NOT NULL,EBR INTEGER NOT NULL,"
    "BESCHREIBUNG VARCHAR(1024),TYPMERKMALE VARCHAR(2048),TYPMERKMALE_PDM VARCHAR(2048),"
    "CONSTRAINT PK_EBR2BRV PRIMARY KEY(ID))"
)
SERIES_SCHEMA = (
    "CREATE CACHED TABLE KIS.EBR(ID INTEGER GENERATED BY DEFAULT AS "
    "IDENTITY(START WITH 1) NOT NULL,NAME VARCHAR(4) NOT NULL,BRV INTEGER NOT NULL,"
    "BESCHREIBUNG VARCHAR(1024),CONSTRAINT PK_EBR PRIMARY KEY(ID),"
    "CONSTRAINT TC_EBR UNIQUE(NAME),CONSTRAINT FK_EBR_BRV FOREIGN KEY(BRV) REFERENCES KIS.BRV(ID))"
)


def indexed_rows(
    path: Path, script: str, table: str, columns: str, nodes: int
) -> Iterator[list[Any]]:
    """Iterate the primary AVL index for one source-declared cached table."""
    match = re.search(rf"^SET TABLE KIS\.{table} INDEX '([\d ]+)'$", script, re.M)
    scale_match = re.search(r"^SET FILES SCALE (\d+)$", script, re.M)
    if match is None or scale_match is None:
        raise DataFormatError(f"Missing KIS {table} index or scale")
    indexes = [int(value) for value in match[1].split()]
    scale = int(scale_match[1])
    if len(indexes) != 2 * nodes + 1 or not 0 <= indexes[-1] <= 100_000 or scale <= 0:
        raise DataFormatError(f"Unsupported KIS {table} index layout")
    size = path.stat().st_size
    seen: set[int] = set()
    pending = [indexes[0]] if indexes[-1] else []
    with path.open("rb") as stream:
        while pending:
            position = pending.pop()
            if position in seen or len(seen) >= indexes[-1]:
                raise DataFormatError(f"Inconsistent KIS {table} index")
            seen.add(position)
            row, left, right = _kis_row(
                stream, position * scale, size, columns=columns, indexes=nodes
            )
            pending.extend(value for value in (left, right) if value > 0)
            yield row
    if len(seen) != indexes[-1]:
        raise DataFormatError(f"KIS {table} row count differs from its index")


def publish(path: Path, data: dict) -> None:
    """Atomically publish generated metadata without damaging an existing asset on failure."""
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            "w", encoding="utf-8", dir=path.parent, delete=False
        ) as stream:
            temporary = Path(stream.name)
            json.dump(data, stream, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def supplement_models(
    database: Path,
    reader: Path,
    models: dict[str, set[tuple[str, str]]],
    source_types: dict[str, set[str]],
) -> dict[str, Any]:
    """Fill missing shared-chassis labels from agreeing exact knowledge-database rows."""
    before = database.stat()
    candidates = {
        code: next(iter(series))
        for code, series in source_types.items()
        if len(series) == 1
        and not any(model_series in series for model_series, _label in models.get(code, set()))
    }
    version = query(reader, database, "SELECT VERSION FROM RG_VERSION WHERE SUBSYSTEM='DATABASE'")
    if version != [{"VERSION": "4.29.14"}]:
        raise DataFormatError("Model supplementation requires source data release 4.29.14")
    if any(not re.fullmatch(r"[A-Z0-9]{4}", code) for code in candidates):
        raise DataFormatError("Invalid source model type selector")
    rows = []
    if candidates:
        # Every selector comes from the validated four-character KIS type field.
        selectors = ",".join(f"'{code}'" for code in sorted(candidates))
        rows = query(
            reader,
            database,
            "SELECT T.NAME type_code,T.ID type_id,V.DRIVEID drive_id,"
            "C.ID characteristic_id,C.NAME name,C.TITLE_ENGB title,R.TITLE_DEDE category "
            "FROM XEP_CHARACTERISTICS T "
            "JOIN XEP_CHARACTERISTICROOTS TR ON TR.ID=T.PARENTID "
            "JOIN XEP_VEHICLES V ON V.TYPEKEYID=T.ID "
            "JOIN XEP_CHARACTERISTICS C ON C.ID=V.CHARACTERISTICID "
            "JOIN XEP_CHARACTERISTICROOTS R ON R.ID=C.PARENTID "
            "WHERE TR.TITLE_DEDE='Typschlüssel' "
            "AND R.TITLE_DEDE IN ('Marke','E-Bezeichnung','Verkaufsbezeichnung') "
            f"AND T.NAME IN ({selectors}) ORDER BY T.NAME,T.ID,R.ID,C.ID,V.DRIVEID",
        )
    recovered = {}
    for code, series in sorted(candidates.items()):
        selected = [row for row in rows if row["type_code"] == code]
        if len({row["type_id"] for row in selected}) != 1:
            continue
        brands = {row["name"] for row in selected if row["category"] == "Marke"}
        series_names = {
            normalize_series(row["name"] or "")
            for row in selected
            if row["category"] == "E-Bezeichnung"
        }
        labels = {row["title"] for row in selected if row["category"] == "Verkaufsbezeichnung"}
        if brands != {"BMW PKW"} or series_names != {series} or len(labels) != 1:
            continue
        label = next(iter(labels))
        if not isinstance(label, str) or not label.strip() or len(label) > 1024:
            continue
        models.setdefault(code, set()).add((series, label))
        recovered[code] = {"series": series, "label": label, "rows": selected}
    source_hash = sha256_file(database)
    after = database.stat()
    if (before.st_size, before.st_mtime_ns) != (after.st_size, after.st_mtime_ns):
        raise DataFormatError("Source model database changed during recovery")
    return {
        "release": "4.29.14",
        "database_sha256": source_hash,
        "reader_sha256": sha256_file(reader),
        "models": recovered,
    }


def recover(
    ista: Path,
    output: Path,
    provenance: Path,
    *,
    type_database: Path | None = None,
    reader: Path | None = None,
) -> None:
    """Decode every declared row, retaining only unambiguous exact BMW type matches."""
    if (type_database is None) != (reader is None):
        raise ValueError("Model database and cipher reader must be supplied together")
    destinations = {output.resolve(), provenance.resolve()}
    if len(destinations) != 2:
        raise ValueError("Model output and provenance must have separate paths")
    if any(
        source.resolve() in destinations for source in (type_database, reader) if source is not None
    ):
        raise ValueError("Model output must not replace a source database or reader")
    root = ista / "Rheingold" if (ista / "Rheingold").is_dir() else ista
    models: dict[str, set[tuple[str, str]]] = {}
    source_types: dict[str, set[str]] = {}
    sources = {}
    for script_path in sorted((root / "PSdZ/kiswb").glob("*/KIS.script")):
        script = script_path.read_text(encoding="utf-8")
        if not {SCHEMA, SERIES_SCHEMA} <= set(script.splitlines()):
            raise DataFormatError(f"Unexpected vehicle-type schema: {script_path}")
        data_path = script_path.with_name("KIS.data")
        series_ids = {
            row[0]: normalize_series(row[1] or "")
            for row in indexed_rows(data_path, script, "EBR", "isis", 3)
        }
        count = 0
        for row in indexed_rows(data_path, script, "FAHRZEUGTYP", "isisss", 2):
            count += 1
            code, label = row[1], row[3]
            linked_series = series_ids.get(row[2], "")
            if linked_series in {"G008", "G026"}:
                source_types.setdefault(code, set()).add(linked_series)
            if label is None or not label.strip():
                continue  # Nullable source descriptions stay unavailable.
            attributes = dict(
                value.split("=", 1) for value in (row[4] or "").split(";") if "=" in value
            )
            series = normalize_series(attributes.get("EBR", ""))
            electric_label = {"G008": "IX3 ", "G026": "I4 "}.get(linked_series)
            if not attributes and electric_label and label.upper().startswith(electric_label):
                # These electric model rows name the model but link the series through EBR.
                series = linked_series
            elif attributes.get("MARKE") != "BM" or not re.fullmatch(r"[FGUI]\d{3}", series):
                continue
            if not re.fullmatch(r"[A-Z0-9]{4}", code) or len(label) > 1024:
                raise DataFormatError(f"Invalid vehicle type: {script_path.parent.name} {code!r}")
            models.setdefault(code, set()).add((series, label))
        with data_path.open("rb") as stream:
            data_hash = hashlib.file_digest(stream, "sha256").hexdigest()
        sources[script_path.parent.name] = {
            "script_sha256": hashlib.sha256(script_path.read_bytes()).hexdigest(),
            "data_sha256": data_hash,
            "rows": count,
        }
    if not sources or not models:
        raise DataFormatError("No vehicle-type catalogue was recovered")
    supplement = (
        supplement_models(type_database, reader, models, source_types)
        if type_database is not None and reader is not None
        else None
    )
    data = {
        "schema": 1,
        "models": {
            code: [{"series": series, "label": label} for series, label in sorted(rows)]
            for code, rows in sorted(models.items())
        },
    }
    publish(output, data)
    publish(
        provenance,
        {
            "sources": sources,
            "types": len(models),
            "asset_sha256": hashlib.sha256(output.read_bytes()).hexdigest(),
            "supplement": supplement,
        },
    )


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("ista", type=Path)
    parser.add_argument("output", type=Path)
    parser.add_argument("provenance", type=Path)
    parser.add_argument("--type-database", type=Path)
    parser.add_argument("--reader", type=Path)
    args = parser.parse_args()
    recover(
        args.ista,
        args.output,
        args.provenance,
        type_database=args.type_database,
        reader=args.reader,
    )
